package run.ikaros.reading; import java.time.Instant; import java.util.UUID; import org.springframework.data.annotation.Id; import org.springframework.data.relational.core.mapping.Table; import org.springframework.data.relational.core.mapping.Column;
@Table("reading_history") public record ReadingHistoryEntity(@Id UUID id,@Column("owner_id") UUID ownerId,@Column("work_id") UUID workId,@Column("chapter_id") UUID chapterId,@Column("started_at") Instant startedAt,@Column("ended_at") Instant endedAt,@Column("duration_seconds") long durationSeconds,@Column("start_locator") String startLocator,@Column("end_locator") String endLocator) {}
